<script setup lang="ts">
import { computed, onUnmounted, ref, watch } from 'vue';
import { invoke } from '@tauri-apps/api/core';
import { refreshFeedback as vRefreshFeedback } from '../../../shared/directives/refreshFeedback';
import { useI18n } from '../uiPorts';
import { Play, Pause, RefreshCw, ShieldCheck, Clock3 } from '@lucide/vue';
const props=defineProps<{projectId?:number;archived?:boolean}>();
const emit=defineEmits<{changed:[]}>();
const { tr } = useI18n();
type Progress={total:number;captured:number;failed:number;skipped:number;pending:number;running:number;uniqueFingerprints:number;newFingerprints:number;attempts:number};
type Task={createdAt?:string;selection?:{roots?:string[];httpsAssets:number;outsideConfirmedScope:number;alreadyHaveFingerprint:number;queued:number};id:string;status:string;reason:string;workers:number;progress:Progress;items:{assetId:number;endpoint:string;status:string;reason:string;attempts:number;fingerprint:string}[]};
type View={roots:string[];tasks:Task[]};
const data=ref<View>(),busy=ref(false),reading=ref(false),error=ref(''),workers=ref(4),expanded=ref(false),taskId=ref('');
let generation=0,sequence=0,disposed=false,timer:ReturnType<typeof setTimeout>|undefined;
let readOwner:{generation:number;promise:Promise<void>}|undefined;
const task=computed(()=>data.value?.tasks.find(t=>t.id===taskId.value)??data.value?.tasks[0]);
const active=computed(()=>task.value&&['running','pausing'].includes(task.value.status));
const done=computed(()=>task.value?task.value.progress.captured+task.value.progress.failed+task.value.progress.skipped:0);
const percent=computed(()=>task.value?.progress.total?Math.min(100,Math.floor(done.value/task.value.progress.total*100)):0);
const taskRoots=computed(()=>task.value?.selection?.roots);
const scopeChanged=computed(()=>!!taskRoots.value&&JSON.stringify([...taskRoots.value].sort())!==JSON.stringify([...(data.value?.roots||[])].sort()));
const historical=computed(()=>!!task.value&&(!taskRoots.value?.length||scopeChanged.value||task.value.id!==data.value?.tasks[0]?.id));
const canStartCurrent=computed(()=>!task.value||task.value.status==='completed'||(!taskRoots.value?.length||scopeChanged.value)&&!active.value);
const hasSelectionCounts=computed(()=>{const selection=task.value?.selection;return !!selection&&(['httpsAssets','outsideConfirmedScope','alreadyHaveFingerprint','queued'] as const).every(key=>typeof selection[key]==='number');});
const labels=computed<Record<string,string>>(()=>({running:tr('正在补采','Capturing'),pausing:tr('正在保存并暂停','Saving and pausing'),paused:tr('已暂停','Paused'),interrupted:tr('应用退出，等待恢复','App exited; waiting to resume'),completed:tr('处理完成','Completed'),failed:tr('执行中断，请检查原因','Stopped with an error; check the reason'),pending:tr('待处理','Pending'),captured:tr('证书已保存','Certificate saved'),skipped:tr('已跳过','Skipped')}));
function schedule(g=generation){clearTimeout(timer);if(!disposed&&g===generation&&data.value?.tasks.some(t=>['running','pausing'].includes(t.status)))timer=setTimeout(()=>void load(g),1500);}
function applyView(value:View){
 const old=task.value;data.value=value;
 if(!value.tasks.some(t=>t.id===taskId.value))taskId.value=value.tasks[0]?.id??'';
 if(task.value&&!['completed','failed'].includes(task.value.status))workers.value=task.value.workers;
 if(old?.status==='running'&&task.value?.status!=='running')emit('changed');
}
function load(g=generation):Promise<void>{
 const projectId=props.projectId;if(!projectId||disposed||g!==generation)return Promise.resolve();
 if(readOwner?.generation===g)return readOwner.promise;
 reading.value=true;const seq=++sequence;
 const promise=(async()=>{
  try{const value=await invoke<View>('certificate_task_action',{projectId,action:'status',args:{}});if(disposed||g!==generation||seq!==sequence)return;applyView(value);error.value='';}
  catch(e){if(g===generation&&seq===sequence&&!disposed)error.value=String(e);}
  finally{if(g===generation&&seq===sequence&&!disposed){readOwner=undefined;reading.value=false;schedule(g);}}
 })();
 readOwner={generation:g,promise};return promise;
}
async function act(action:string,retryFailed=false){
 if(!props.projectId||busy.value||reading.value||props.archived)return;
 const projectId=props.projectId,g=generation;clearTimeout(timer);busy.value=true;error.value='';
 try{const result=await invoke<View>('certificate_task_action',{projectId,action,args:action==='start'?{workers:workers.value,timeoutSeconds:8}:{taskId:task.value?.id,retryFailed}});if(g===generation&&!disposed){taskId.value=result.tasks[0]?.id??taskId.value;applyView(result);await load(g);if(g===generation&&!disposed)emit('changed');}}
 catch(e){if(g===generation&&!disposed)error.value=String(e);}finally{if(g===generation&&!disposed){busy.value=false;schedule(g);}}
}
watch(taskId,()=>{expanded.value=false;});
watch(()=>props.projectId,()=>{generation++;sequence++;clearTimeout(timer);readOwner=undefined;data.value=undefined;taskId.value='';expanded.value=false;error.value='';busy.value=false;reading.value=false;void load();},{immediate:true});
onUnmounted(()=>{disposed=true;generation++;sequence++;clearTimeout(timer);});
</script>
<template>
 <section class="certificate-task-panel" :aria-label="tr('TLS 证书补采', 'TLS certificate capture')">
  <header class="certificate-task-heading">
   <div class="certificate-task-title"><span class="certificate-task-icon"><ShieldCheck :size="19"/></span><div><h3>{{ tr('读取缺失的 TLS 证书', 'Read missing TLS certificates') }}</h3><p>{{ tr('只读取证书，不获取网页；不消耗 FOFA / Hunter 积分。', 'Reads certificates only, never web pages. Uses no FOFA / Hunter points.') }}</p></div></div>
   <button type="button" v-refresh-feedback="{scope:projectId,busy:reading,error}" class="button ghost compact certificate-refresh" :disabled="busy||reading||!projectId" data-certificate-action="refresh" :aria-label="tr('刷新证书补采进度', 'Refresh certificate capture progress')" @click="load()"><RefreshCw :size="14" :class="{spinning:reading}"/>{{reading?tr('正在读取…', 'Reading…'):tr('刷新进度', 'Refresh progress')}}</button>
  </header>
  <div class="certificate-task-scope">
   <span class="scope-label">{{ tr('当前已确认范围', 'Confirmed scope') }}</span><div v-if="data?.roots.length" class="scope-domains"><span v-for="root in data.roots" :key="root">{{root}}</span></div><span v-else class="scope-empty">{{reading?tr('正在读取范围…', 'Reading scope…'):tr('尚未设置，请先在「发现资产」确认范围。', 'Not set. Confirm a scope in "Discover assets" first.')}}</span>
   <small>{{ tr('新补采按此范围选择 HTTPS 资产；范围外的 IP 入口不会自动加入。', 'New captures select HTTPS assets in this scope; out-of-scope IP entries are not added automatically.') }}</small>
  </div>
  <div class="certificate-task-toolbar">
   <label v-if="data&&data.tasks.length>1" class="task-history"><span><Clock3 :size="13"/>{{ tr('任务记录', 'Task history') }}</span><select v-model="taskId" :aria-label="tr('证书补采任务历史', 'Certificate capture task history')" :disabled="busy"><option v-for="item in data.tasks" :key="item.id" :value="item.id">{{item.createdAt||item.id.slice(0,8)}} · {{labels[item.status]||item.status}}</option></select></label>
   <div v-else-if="task" class="task-record-label"><span>{{historical?tr('历史任务', 'Past task'):tr('最近任务', 'Latest task')}}</span><strong>{{task.createdAt||task.id.slice(0,8)}}</strong></div>
   <label v-if="canStartCurrent" class="task-workers"><span>{{ tr('新任务同时读取', 'Parallel reads for new tasks') }}</span><select v-model.number="workers" :aria-label="tr('TLS 补采并发数量', 'TLS capture concurrency')" :disabled="busy||reading"><option :value="1">{{ tr('1 台', '1 host') }}</option><option :value="4">{{ tr('4 台', '4 hosts') }}</option><option :value="8">{{ tr('8 台', '8 hosts') }}</option><option :value="16">{{ tr('16 台', '16 hosts') }}</option></select></label>
   <div class="certificate-task-actions">
    <button type="button" v-if="canStartCurrent" class="button primary" :disabled="busy||reading||!projectId||archived||!data?.roots.length" data-certificate-action="start" @click="act('start')"><Play :size="14"/>{{busy?tr('正在接续…', 'Continuing…'):task?tr('按当前范围检查并补采', 'Check and capture for current scope'):tr('开始补采缺失证书', 'Start capturing missing certificates')}}</button>
    <button type="button" v-if="task&&['running','pausing'].includes(task.status)" class="button ghost" :disabled="busy||reading||task.status==='pausing'||archived" data-certificate-action="pause" @click="act('pause')"><Pause :size="14"/>{{task.status==='pausing'?tr('正在暂停…', 'Pausing…'):tr('暂停补采', 'Pause capture')}}</button>
    <button type="button" v-if="task&&['paused','interrupted','failed'].includes(task.status)" class="button" :class="{primary:!scopeChanged,ghost:scopeChanged}" :disabled="busy||reading||archived" data-certificate-action="resume" @click="act('resume')"><Play :size="14"/>{{busy?tr('正在接续…', 'Continuing…'):historical?tr('继续此历史任务', 'Resume this past task'):tr('继续未完成项', 'Resume unfinished items')}}</button>
    <button type="button" v-if="task&&!active&&task.progress.failed>0" class="button ghost" :disabled="busy||reading||archived" data-certificate-action="retry" @click="act('resume',true)">{{ tr(`重试失败项 · ${task.progress.failed}`, `Retry failed · ${task.progress.failed}`) }}</button>
   </div>
  </div>
  <template v-if="task">
   <div v-if="scopeChanged||!taskRoots?.length" class="certificate-scope-change" role="status"><strong>{{taskRoots?.length?tr('当前查看的是旧范围的任务记录', 'You are viewing a task from an earlier scope'):tr('此历史任务没有记录创建时的范围', 'This past task did not record its scope when created')}}</strong><span>{{ tr(`任务范围：${taskRoots?.join('、')||'未记录'}；当前范围：${data?.roots.join('、')||'尚未设置'}。`, `Task scope: ${taskRoots?.join(', ')||'not recorded'}; current scope: ${data?.roots.join(', ')||'not set'}.`) }}</span><span>{{ tr('下方统计仅属于此任务，不代表当前范围的补采进度。继续旧任务时，范围外项目会跳过。', 'The figures below belong to this task only, not to capture progress for the current scope. Resuming an old task skips out-of-scope items.') }}</span></div>
   <div class="certificate-task-progress-heading"><div><strong>{{historical?tr('历史任务进度', 'Past task progress'):tr('任务进度', 'Task progress')}}</strong><span v-if="taskRoots?.length&&!scopeChanged">{{taskRoots.join(tr('、', ', '))}}</span></div><span class="certificate-task-status" :class="{active:active,failed:task.status==='failed'}">{{labels[task.status]||task.status}}<template v-if="active">{{ tr(` · ${task.workers} 台并发`, ` · ${task.workers} in parallel`) }}</template></span></div>
   <div class="certificate-task-metrics">
    <div><span>{{ tr('已处理资产', 'Assets processed') }}</span><strong>{{done.toLocaleString()}}<small> / {{task.progress.total.toLocaleString()}}</small></strong></div>
    <div><span>{{ tr('证书已保存', 'Certificates saved') }}</span><strong>{{task.progress.captured.toLocaleString()}}</strong></div>
    <div><span>{{ tr('失败', 'Failed') }}</span><strong :class="{warning:task.progress.failed>0}">{{task.progress.failed.toLocaleString()}}</strong></div>
    <div><span>{{ tr('跳过', 'Skipped') }}</span><strong>{{task.progress.skipped.toLocaleString()}}</strong></div>
    <div><span>{{ tr('唯一指纹', 'Unique fingerprints') }}</span><strong>{{task.progress.uniqueFingerprints.toLocaleString()}}</strong></div>
    <div><span>{{ tr('新增指纹', 'New fingerprints') }}</span><strong>{{task.progress.newFingerprints.toLocaleString()}}</strong></div>
   </div>
   <progress :value="done" :max="Math.max(1,task.progress.total)" :aria-label="tr(`证书补采进度 ${percent}%`, `Certificate capture progress ${percent}%`)"/>
   <p class="certificate-task-note">{{task.reason}}{{task.reason&&/[。！？]$/.test(task.reason)?'':'。'}}<span v-if="!task.progress.total">{{historical?tr('此历史任务没有待补采项。', 'This past task has nothing to capture.'):tr('本任务没有待补采项。', 'This task has nothing to capture.')}}</span></p>
   <details class="certificate-task-details" :open="expanded" @toggle="expanded=($event.target as HTMLDetailsElement).open"><summary>{{ tr(`任务详情与采集说明 · ${task.id.slice(0,8)}`, `Task details and collection notes · ${task.id.slice(0,8)}`) }}</summary>
    <p v-if="hasSelectionCounts&&task.selection" class="certificate-task-selection">{{ tr(`创建时 ${task.selection.httpsAssets.toLocaleString()} 条 HTTPS 记录 · 范围外 ${task.selection.outsideConfirmedScope.toLocaleString()} 条 · 已有指纹 ${task.selection.alreadyHaveFingerprint.toLocaleString()} 条 · 本任务入队 ${task.selection.queued.toLocaleString()} 条。`, `At creation: ${task.selection.httpsAssets.toLocaleString()} HTTPS records · ${task.selection.outsideConfirmedScope.toLocaleString()} out of scope · ${task.selection.alreadyHaveFingerprint.toLocaleString()} already fingerprinted · ${task.selection.queued.toLocaleString()} queued for this task.`) }}</p>
    <div v-if="task.items.length" class="certificate-task-table"><table><thead><tr><th>{{ tr('资产', 'Asset') }}</th><th>{{ tr('状态', 'Status') }}</th><th>{{ tr('说明', 'Details') }}</th></tr></thead><tbody><tr v-for="item in task.items" :key="item.assetId"><td>{{item.endpoint}}</td><td>{{labels[item.status]||item.status}}</td><td>{{item.reason||tr('等待执行', 'Waiting')}}</td></tr></tbody></table></div>
    <p>{{ tr('同一张证书部署在多台资产上，只计一个唯一指纹。补采不会自动查询 Hunter，也不会解除隔离。最多展示 20 条；完整进度由任务记录保存，暂停会先保存当前握手结果。', 'A certificate deployed on several assets counts as one unique fingerprint. Capture never queries Hunter automatically and never lifts quarantine. Up to 20 items are shown; full progress is kept in the task record, and pausing saves the current handshake results first.') }}</p>
   </details>
  </template>
  <p v-else-if="!reading&&!error" class="certificate-task-empty">{{ tr('尚无补采任务。确认范围后，点击开始即可自动处理缺少指纹的 HTTPS 资产。', 'No capture tasks yet. Once a scope is confirmed, click Start to process HTTPS assets that lack a fingerprint.') }}</p>
  <p v-if="error" class="certificate-task-error" role="alert">{{error}}</p>
 </section>
</template>
<style scoped>
.certificate-task-panel{margin:0 0 20px;padding:20px;border:1px solid var(--line,var(--ui-line));border-radius:var(--radius-lg);background:var(--app-surface,var(--ui-surface));font-size:var(--text-strong);line-height:1.6;min-width:0;box-sizing:border-box}.certificate-task-heading{display:flex;justify-content:space-between;align-items:flex-start;gap:16px}.certificate-task-title{display:flex;align-items:flex-start;gap:10px;min-width:0}.certificate-task-icon{display:flex;align-items:center;justify-content:center;width:34px;height:34px;flex:0 0 34px;border-radius:var(--radius-md);background:var(--app-bg,var(--ui-surface-raised));color:var(--muted,var(--ui-muted))}.certificate-task-panel h3{font-size:var(--text-heading);line-height:1.5;margin:0 0 3px}.certificate-task-panel p{margin:0;color:var(--muted,var(--ui-muted));font-size:var(--text-body)}.certificate-task-panel .button{display:inline-flex;align-items:center;justify-content:center;gap:8px;white-space:nowrap;min-height:36px;padding:8px 12px;font:inherit;font-size:var(--text-body)}.certificate-refresh{flex-shrink:0}.certificate-task-scope{display:grid;grid-template-columns:104px minmax(0,1fr);align-items:start;gap:6px 12px;padding:12px 14px;border:1px solid var(--line,var(--ui-line));border-radius:var(--radius-md);background:var(--app-bg,var(--ui-surface-raised));margin-top:16px;font-size:var(--text-body)}.scope-label{font-size:var(--text-meta);color:var(--muted);padding-top:3px}.scope-domains{display:flex;flex-wrap:wrap;gap:6px;min-width:0}.scope-domains>span{padding:2px 8px;border:1px solid var(--line);border-radius:var(--radius-sm);background:var(--app-surface,var(--ui-surface));overflow-wrap:anywhere}.certificate-task-scope>small{grid-column:2;color:var(--muted);font-size:var(--text-meta)}.scope-empty{color:var(--muted)}.certificate-task-toolbar{display:flex;align-items:flex-end;gap:14px;margin:16px 0;flex-wrap:wrap}.certificate-task-toolbar label,.task-record-label{display:flex;flex-direction:column;gap:6px;min-width:0;font-size:var(--text-meta);color:var(--muted)}.certificate-task-toolbar label>span{display:flex;align-items:center;gap:6px}.task-history{flex:1 1 260px;max-width:400px}.task-record-label{flex:1 1 180px}.task-record-label>strong{color:var(--text,var(--ui-ink));font-size:var(--text-body);line-height:36px;font-weight:500}.certificate-task-toolbar select{box-sizing:border-box;min-width:76px;max-width:100%;height:36px;padding:8px 28px 8px 10px;border:1px solid var(--line);border-radius:var(--radius-sm);background:var(--app-surface,var(--ui-surface));font:inherit;font-size:var(--text-body);color:var(--text,var(--ui-ink))}.task-history select{width:100%}.certificate-task-actions{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin-left:auto}.certificate-scope-change{display:flex;flex-direction:column;gap:3px;padding:10px 12px;border:1px solid color-mix(in srgb, var(--amber) 40%, var(--ui-line));border-radius:var(--radius-sm);background:color-mix(in srgb, var(--amber) 6%, var(--ui-surface));font-size:var(--text-meta);color:color-mix(in srgb, var(--amber) 82%, var(--ui-ink));margin-bottom:14px}.certificate-scope-change strong{font-size:var(--text-body)}.certificate-scope-change span{overflow-wrap:anywhere}.certificate-task-progress-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:10px;margin:16px 0 10px}.certificate-task-progress-heading>div{display:flex;align-items:center;gap:10px;flex-wrap:wrap;min-width:0}.certificate-task-progress-heading strong{font-size:var(--text-body)}.certificate-task-progress-heading>div>span{font-size:var(--text-meta);color:var(--muted);overflow-wrap:anywhere}.certificate-task-status{padding:2px 8px;border:1px solid var(--line);border-radius:var(--radius-sm);color:var(--muted);font-size:var(--text-meta);flex-shrink:0}.certificate-task-status.active{background:var(--ui-surface-sunken);color:color-mix(in srgb, var(--green) 82%, var(--ui-ink));border-color:color-mix(in srgb, var(--green) 24%, var(--ui-line))}.certificate-task-status.failed{color:color-mix(in srgb, var(--red) 82%, var(--ui-ink));border-color:color-mix(in srgb, var(--red) 32%, var(--ui-line));background:color-mix(in srgb, var(--red) 5%, var(--ui-surface))}.certificate-task-metrics{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:8px}.certificate-task-metrics>div{padding:10px 12px;border:1px solid var(--line);border-radius:var(--radius-sm);min-width:0;background:var(--app-surface,var(--ui-surface))}.certificate-task-metrics>div>span{display:block;font-size:var(--text-meta);color:var(--muted);margin-bottom:6px}.certificate-task-metrics strong{display:block;color:var(--text,var(--ui-ink));font-size:var(--text-title);font-variant-numeric:tabular-nums;line-height:1.4;overflow-wrap:anywhere}.certificate-task-metrics strong small{font-weight:400;font-size:var(--text-body);color:var(--muted)}.certificate-task-metrics .warning{color:color-mix(in srgb, var(--amber) 82%, var(--ui-ink))}.certificate-task-panel progress{display:block;width:100%;height:6px;accent-color:var(--blue,#2878ff);margin:12px 0}.certificate-task-panel .certificate-task-note{font-size:var(--text-meta);overflow-wrap:anywhere}.certificate-task-details{border-top:1px solid var(--line);padding-top:12px;margin-top:14px}.certificate-task-details summary{cursor:pointer;color:var(--muted);font-size:var(--text-meta)}.certificate-task-details p{font-size:var(--text-meta);overflow-wrap:anywhere;margin-top:10px}.certificate-task-table{max-height:260px;overflow:auto;margin:10px 0}table{border-collapse:collapse;width:100%;font-size:var(--text-body)}th,td{text-align:left;padding:8px;border-bottom:1px solid var(--line);overflow-wrap:anywhere;max-width:360px}.certificate-task-panel .certificate-task-empty{padding:12px 0;font-size:var(--text-body)}.certificate-task-panel .certificate-task-error{color:var(--danger,color-mix(in srgb, var(--red) 82%, var(--ui-ink)));margin-top:12px;overflow-wrap:anywhere}@media(max-width:1000px){.certificate-task-metrics{grid-template-columns:repeat(3,minmax(0,1fr))}.certificate-task-actions{margin-left:0}.task-history{max-width:none}}@media(max-width:600px){.certificate-task-panel{padding:14px}.certificate-task-heading{flex-wrap:wrap;gap:10px}.certificate-task-heading .certificate-refresh{margin-left:44px}.certificate-task-scope{grid-template-columns:1fr;gap:8px}.certificate-task-scope>small{grid-column:1}.certificate-task-toolbar{gap:10px}.task-history{flex-basis:100%}.certificate-task-actions{width:100%;align-items:stretch}.certificate-task-actions .button{flex:1 1 auto;white-space:normal}.certificate-task-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.certificate-task-progress-heading{flex-wrap:wrap}.task-record-label>strong{line-height:1.6}}
</style>
